import {subjects,copyDefaults,makeCards,chooseSession,recordProgress,statusOf,audioEntries} from './core.mjs?v=unlimited-default-7';
import {BuddyAudio} from './audio.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='kinder-buddy-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}');}catch{}
let settings={...copyDefaults(),...saved.settings},progress=saved.progress||{},stars=Number(saved.stars)||0,sessions=Number(saved.sessions)||0;
if(!['','catholic','nonCatholic'].includes(settings.track))settings.track='';
settings.enabled=Array.isArray(settings.enabled)?settings.enabled.filter(n=>subjects.some(s=>s.id===n)):subjects.map(s=>s.id);
if(saved.settings?.activityLimitDefault!==1){settings.length=0;settings.activityLimitDefault=1;}
settings.length=[0,5,8,12].includes(Number(settings.length))?Number(settings.length):0;
settings.pause=[5,8,12,20].includes(Number(settings.pause))?Number(settings.pause):8;
let data,cards,manifest,page='home',filter='All',topic=0,session=null,partFocus='',audioState='idle',timer=null,flowToken=0,toastTimer;
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',book:'<path d="M12 6c-3-2-6-3-10-2v15c4-1 7 0 10 2 3-2 6-3 10-2V4c-4-1-7 0-10 2v15"/>',star:'<path d="m12 2 3.1 6.3 6.9 1-5 4.9 1.2 6.8L12 17.8 5.8 21 7 14.2 2 9.3l6.9-1z"/>',parent:'<path d="M20 21v-2a5 5 0 0 0-5-5H9a5 5 0 0 0-5 5v2"/><circle cx="12" cy="6" r="4"/>',play:'<path d="m8 4 12 8-12 8z"/>',sound:'<path d="m11 5-6 4H2v6h3l6 4zM15 8a6 6 0 0 1 0 8M18 4a11 11 0 0 1 0 16"/>',back:'<path d="m14 5-7 7 7 7"/>',next:'<path d="m9 5 7 7-7 7"/>',help:'<circle cx="12" cy="12" r="10"/><path d="M9 8a3 3 0 1 1 4 3c-1 0-1 1-1 3m0 3h.01"/>',pause:'<path d="M8 4v16M16 4v16"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.star}</svg>`;
const owl=()=>`<svg class="mascot" viewBox="0 0 340 300" role="img" aria-label="Ollie the friendly owl"><circle cx="178" cy="135" r="109" fill="#d4e6d7"/><path d="M30 248c52-20 88-7 143-11s93-10 138 8" fill="none" stroke="#becfb5" stroke-width="3" stroke-linecap="round"/><path d="M253 229q-23-15-6-42 24 10 6 42m3 0q-3-28 23-38 7 28-23 38" fill="#88ad82"/><path d="M55 230q-7-24 11-34 13 23-11 34" fill="#9ebb8a"/><path d="m90 231 146 0" stroke="#9c7750" stroke-width="10" stroke-linecap="round"/><path d="M113 100 102 56 151 74q24-8 47 0l43-18-8 47q18 34 11 74-9 48-69 48-68-1-74-49-5-41 12-76" fill="#d19b59"/><ellipse cx="176" cy="157" rx="65" ry="63" fill="#edc47d"/><path d="M109 123q-32 40 4 76l19-21" fill="#bd824c"/><path d="M234 123q34 35-2 75l-16-17" fill="#bd824c"/><ellipse cx="146" cy="126" rx="34" ry="38" fill="#fff7df"/><ellipse cx="203" cy="126" rx="34" ry="38" fill="#fff7df"/><circle cx="151" cy="130" r="10" fill="#344840"/><circle cx="198" cy="130" r="10" fill="#344840"/><circle cx="154" cy="126" r="3" fill="white"/><circle cx="201" cy="126" r="3" fill="white"/><path d="m163 151 13 15 12-15" fill="#be713e"/><path d="m156 177 6 5m14-2 5 5m14-8 5 4m-38 12 6 5m17 0 5 4" stroke="#c49456" stroke-width="3" stroke-linecap="round"/><path d="m145 220-1 11m11-10 1 10m39-10-1 10m10-11 2 11" stroke="#a96f43" stroke-width="6" stroke-linecap="round"/><path d="m278 67 3 8 8 3-8 3-3 8-3-8-8-3 8-3m-212 49 2 6 6 2-6 2-2 6-2-6-6-2 6-2" fill="#edbc53"/><path d="M267 125q12-12 22 0m-6-12q10-9 17-1" stroke="#a3bfa5" stroke-width="3" fill="none" stroke-linecap="round"/></svg>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify({settings,progress,stars,sessions}));}catch{toast('Progress could not be saved on this device.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),6000);}
function stop(){flowToken++;clearTimeout(timer);audio?.stop();}
function go(where){stop();page=where;render();window.scrollTo({top:0,behavior:'instant'});}
function trackName(){return settings.track==='catholic'?'Roman Catholic':settings.track==='nonCatholic'?'Non-Roman Catholic':'Choose in parent settings';}
function brand(){return '<div class="brand"><img src="assets/favicon.svg" alt=""><div>Kinder Buddy<small>LITTLE STEPS, BIG DISCOVERIES</small></div></div>';}
function nav(mobile=false){return [['home','home','My practice'],['lessons','book','My lessons'],['stars','star','My stars'],['parent','parent','Grown-ups']].map(([p,i,l])=>`<button data-action="${p==='parent'?'parent':'page'}" data-page="${p}" class="${mobile?'':'nav-btn '}${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}${l}</button>`).join('');}
function render(){
 const content=page==='home'?home():page==='lessons'?lessons():page==='topic'?topicPage():page==='practice'?practice():page==='finish'?finish():page==='parent'?parent():starPage();
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<nav class="side-nav" aria-label="Main">${nav()}</nav><div class="side-note"><div class="seed">🌱</div><b>A little practice, every day.</b><br>You’re growing something wonderful.</div><span class="asset-credit">Kindergarten · Oral Test 7<br>A little help from Ollie</span></aside><main class="main"><div class="mobile-logo">${brand()}<span class="pill gold">★ ${stars}</span></div>${content}</main><nav class="mobile-bar" aria-label="Mobile navigation">${nav(true)}</nav></div>`;
 updateAudioState();
}
function home(){return `<header class="topbar"><div><div class="eyebrow">YOUR LITTLE LEARNING PLACE</div><h2 class="top-title">Hello, little explorer! <span aria-hidden="true">☀️</span></h2></div><span class="pill gold">★ ${stars} practice stars</span></header><section class="hero"><div class="hero-copy"><div class="eyebrow">A LITTLE ADVENTURE AWAITS</div><h1>Ready to learn<br>something new?</h1><p>Listen, say it out loud, and give it a try.<br>Ollie will help you along the way.</p><button class="primary" data-action="start">${icon('play')} Let’s start!</button><div class="session-note"><span>◷ Reviewer order · resumes where you stopped</span><span>✦ ${settings.length===0?'No activity limit · parent chooses breaks':settings.length+' little activities'}</span></div></div><div class="hero-art">${owl()}</div></section><div class="section-row"><h2>Where shall we explore?</h2><button class="text-btn" data-action="page" data-page="lessons">All lessons →</button></div><div class="lesson-grid">${subjects.map(lessonCard).join('')}</div><div class="bottom-tip"><span style="font-size:25px">💛</span><div><b>You don’t have to know it yet.</b><br>Tap “Help me” whenever you need a little hand.</div></div>`;}
function lessonCard(s){const sc=cards.filter(c=>c.item===s.id&&!c.supplement),done=sc.filter(c=>progress[c.id]?.views).length;return `<button class="lesson" data-action="topic" data-id="${s.id}" style="--tint:${s.tint}"><span class="lesson-arrow">↗</span><span class="lesson-icon" aria-hidden="true">${s.icon}</span><h3>${s.title}</h3><p>${s.subtitle}</p><div class="lesson-footer"><span>${s.tag}</span><span class="tiny-progress"><i style="width:${sc.length?done/sc.length*100:0}%"></i></span></div></button>`;}
function lessons(){return `<div class="eyebrow">CHOOSE A LITTLE ADVENTURE</div><h1 class="page-title mt">My lessons</h1><p class="page-sub">Something to read. Something to say. Something new to discover.</p><div class="filter-row">${['All','English','Explore','Languages','Religion'].map(f=>`<button class="chip ${f===filter?'active':''}" data-action="filter" data-value="${f}">${f}</button>`).join('')}</div><div class="lesson-grid">${subjects.filter(s=>filter==='All'||s.group===filter).map(lessonCard).join('')}</div>`;}
function topicPage(){const s=subjects.find(s=>s.id===topic),sc=cards.filter(c=>c.item===topic&&!c.supplement);const religion=[8,9].includes(topic);return `<div class="activity-head"><button class="back-btn" aria-label="Back to lessons" data-action="page" data-page="lessons">${icon('back')}</button><div class="activity-title">${s.title}<small>School reviewer · Item ${s.id}</small></div><span style="font-size:31px">${s.icon}</span></div><section class="parent-section"><h1 class="page-title">${s.title}</h1><p>${s.subtitle}. ${religion?`<span class="track-badge">${trackName()}</span>`:''}</p>${religion&&!settings.track?`<div class="callout">A grown-up can choose your religion lesson first.</div><button class="primary" data-action="parent">Choose religion option</button>`:`<div class="button-row"><button class="primary" data-action="start" data-id="${topic}">${icon('play')} Let’s practice</button>${topic===8?'<button class="secondary" data-action="full-prayer">Listen to all</button><button class="secondary" data-action="build-prayer">Build it up</button>':''}<button class="secondary" data-action="start" data-id="${topic}" data-all="true">Practice all ${sc.length}</button></div>`}</section>${sc.length?`<div class="section-row"><h2>Little steps in this lesson</h2><span class="caption">${sc.length} activities</span></div><div class="parent-section">${sc.map((c,i)=>`<div class="progress-row"><div><b>${i+1}.</b> ${esc(label(c))}<span class="status">${esc(statusOf(progress[c.id]))}</span></div><button data-action="card" data-key="${esc(c.id)}" aria-label="Practice ${esc(label(c))}">Try it →</button></div>`).join('')}</div>`:''}${topic===5?`<section class="parent-section"><h2>Meet the insect parts</h2><p>Point to a part, hear its name, then practice naming it.</p><div class="button-row"><button class="secondary" data-action="anatomy" data-id="wasp">🐝 Wasp parts</button><button class="secondary" data-action="anatomy" data-id="butterfly">🦋 Butterfly parts</button></div></section>`:''}`;}
function label(c){if(['word','phrase','prayer','shape','number','animal','german'].includes(c.type))return c.type==='german'?`${c.english} → ${c.answer}`:c.answer;if(c.type==='adjective')return c.triple.join(' → ');return c.prompt;}
function begin(subject=0,all=false,individual=null,questionsOnly=false){
 stop();const q=individual?[individual]:all?cards.filter(c=>c.item===subject&&!c.supplement):chooseSession(cards,progress,settings,subject);
 if(!q.length){toast([8,9].includes(subject)?'Choose a religion option in Grown-ups first.':'Choose at least one lesson in Grown-ups.');return;}
 session={q,index:0,subject,reviewerOrder:!subject&&!individual&&!all,mode:questionsOnly?'recall':settings.mode,questionsOnly,revealed:false,helped:false,selected:null,feedback:'',done:0,correct:0,repeated:new Set(),completed:false};page='practice';prepareCard(!settings.introduced);
}
function card(){return session?.q[session.index];}
function isMemory(c){return [1,2,3,8,11,12].includes(c.item);}
function prepareCard(welcome=false){stop();partFocus='';const c=card();session.revealed=session.mode==='learn'&&isMemory(c);session.helped=false;session.selected=null;session.feedback='';session.choices=c.choices?[...c.choices].sort(()=>Math.random()-.5):[];render();window.scrollTo({top:0,behavior:'instant'});if(welcome){const token=flowToken;audio.play('Hello, little explorer! I am Ollie. Listen, then say your answer out loud. Tap Again to hear it again. Tap Help me for a little help. Tap Next when you are ready. Let’s begin!','en-US','cue:welcome',settings.slow).then(ok=>{if(ok){settings.introduced=true;save();}if(token===flowToken&&page==='practice')playInitial();});}else playInitial();}
async function playInitial(){const token=flowToken,c=card();const part=session.revealed?'answer':'prompt';const ok=await audio.play(c[part],c[part+'Lang'],c.id+':'+part,settings.slow);if(token!==flowToken||!ok||page!=='practice')return;if(settings.auto){countdown(settings.pause,()=>{if(session.questionsOnly)next();else if(!session.revealed)reveal(false,true);else next();});}}
function countdown(seconds,done){const token=flowToken;let left=seconds;const tick=()=>{if(token!==flowToken||page!=='practice')return;const p=$('#player-line');if(p)p.textContent=`Your turn · ${left} seconds. Tap pause for more time.`;if(left--<=0){done();return;}timer=setTimeout(tick,1000);};tick();}
async function reveal(help=true,automated=false){stop();const c=card();if(help){session.helped=true;progress=recordProgress(progress,c.id,'help');save();}session.revealed=true;render();const token=flowToken;const ok=await audio.play(c.answer,c.answerLang,c.id+':answer',settings.slow);if(automated&&ok&&token===flowToken)countdown(settings.pause,()=>next());}
function next(){stop();const c=card();progress=recordProgress(progress,c.id,'view');stars++;session.done++;if(session.reviewerOrder)settings.reviewerAfter={...settings.reviewerAfter,[settings.track||'none']:c.id};if(!session.reviewerOrder&&session.helped&&!session.repeated.has(c.id)&&session.q.length<settings.length+3){session.q.splice(Math.min(session.index+3,session.q.length),0,c);session.repeated.add(c.id);}save();if(++session.index>=session.q.length){sessions++;session.completed=true;save();page='finish';render();audio.play('Wonderful practice! You tried, you learned, and you grew. Time for a little break.','en-US','cue:finish',settings.slow);}else prepareCard();}
function practice(){const c=card(),s=subjects.find(s=>s.id===c.item);return `<div class="activity-head"><button class="back-btn" aria-label="Leave practice" data-action="leave">${icon('back')}</button><div class="activity-title">${s.title}<small>${c.item===8||c.item===9?trackName():'One little step at a time'}</small></div><span class="pill">${session.index+1} / ${session.q.length}</span></div><div class="practice-track"><i style="width:${session.index/session.q.length*100}%"></i></div><div class="mode-switch" aria-label="Practice mode"><button data-action="mode" data-value="learn" class="${session.mode==='learn'?'active':''}">Listen & learn</button><button data-action="mode" data-value="recall" class="${session.mode==='recall'?'active':''}">Try myself</button></div><article class="practice-card" id="practice-card"><div class="stage-label"><span class="sound-dot"></span><span id="stage-text">${session.revealed?'Listen, then say it':'Your turn to try'}</span></div>${cardBody(c)}${session.feedback?`<div class="feedback" role="status">${esc(session.feedback)}</div>`:''}${!session.revealed&&session.choices.length?`<div class="caption">Say it out loud. You can also tap an answer.</div><div class="choices">${session.choices.map((v,i)=>`<button class="choice ${session.selected===v?'incorrect':''}" data-action="choice" data-index="${i}">${esc(v)}</button>`).join('')}</div>`:''}${c.parts&&session.revealed?`<div class="parts">${c.parts.map(p=>`<button class="chip ${partFocus===p?'active':''}" data-action="part" data-value="${esc(p)}">${esc(p)}</button>`).join('')}</div>`:''}</article><div class="practice-actions"><button class="secondary" data-action="replay">${icon('sound')} Again</button><button class="secondary" data-action="reveal">${icon('help')} ${session.revealed?'Say with me':'Help me'}</button><button class="primary" data-action="next">Next ${icon('next')}</button></div><div class="player-line" id="player-line" role="status" aria-live="polite">Your turn. Take your time.</div><div class="session-toggle"><button class="text-btn" data-action="leave">Take a break</button><button class="text-btn" data-action="pause">${audioState==='playing'?'Pause audio':'Pause / more time'}</button><label><input type="checkbox" data-setting="auto" ${settings.auto?'checked':''}> Keep going for me</label></div><p class="audio-note" id="audio-note"></p>`;}
const shapePaths={circle:'<circle cx="90" cy="80" r="63"/>',square:'<rect x="30" y="20" width="120" height="120" rx="4"/>',rectangle:'<rect x="8" y="35" width="164" height="90" rx="4"/>',oval:'<ellipse cx="90" cy="80" rx="82" ry="50"/>',triangle:'<path d="m90 12 80 133H10z"/>',diamond:'<path d="m90 7 65 73-65 73-65-73z"/>',star:'<path d="m90 8 22 48 52 5-40 35 13 52-47-27-46 27 12-52-40-35 52-5z"/>',heart:'<path d="M90 144C-28 69 20-19 90 38 160-19 208 69 90 144"/>'};
function anatomy(c){const coords={wasp:{head:[78,26],eye:[75,21],antenna:[82,7],mouth:[87,35],thorax:[57,36],wing:[39,18],leg:[66,74],abdomen:[32,62]},butterfly:{head:[76,43],eye:[76,37],antenna:[74,17],proboscis:[89,53],thorax:[67,59],wing:[34,42],leg:[80,70],abdomen:[48,85]}};const p=c.part||partFocus,xy=coords[c.diagram]?.[p];return `<div class="anatomy"><img src="assets/${esc(c.diagram)}.webp" alt="${esc(c.diagram)} anatomy">${xy?`<span class="part-dot" style="left:${xy[0]}%;top:${xy[1]}%" aria-label="Highlighted part">•</span>`:''}</div>`;}
function cardBody(c){const r=session.revealed;
 if(c.type==='word'){const w=esc(c.answer),pat=esc(c.pattern),index=w.lastIndexOf(pat),highlight=index>=0?w.slice(0,index)+'<mark>'+pat+'</mark>'+w.slice(index+pat.length):w;return `<div class="word">${session.mode==='learn'?highlight:w}</div><p class="caption">${r?'Listen. Now you say it!':'Read this word out loud.'}</p>`;}
 if(c.type==='phrase')return `<div class="word phrase">${esc(c.answer)}</div><p class="caption">${r?'Listen, then read with me.':'Read the whole phrase. You can do it.'}</p>`;
 if(c.type==='adjective')return `<p class="question small">${r?'Let’s say all three.':`What comes after “${esc(c.triple[0])}”?`}</p><div class="adjective-row">${c.triple.map((v,i)=>`<div class="adjective"><small>${['Positive','Comparative','Superlative'][i]}</small><b>${r||i===0?esc(v):'?'}</b></div>`).join('')}</div><p class="caption">${!r?'Say both missing words. The choices check the last word.':'Your turn: say the three forms together.'}</p>`;
 if(c.type==='math')return `<p class="question">What number comes after…</p><div class="question-number">${c.number} <span style="font-weight:400;color:#acbbaa">→</span> ${r?esc(c.answer):'?'}</div>`;
 if(c.type==='shape')return `<p class="question small">Anong hugis ito?</p><svg class="shape-pic" viewBox="0 0 180 160" fill="#e6ac5b" stroke="#c99143" stroke-width="3" aria-label="Shape to name">${shapePaths[c.shape]}</svg>${r?`<div class="answer">${esc(c.answer)}</div>`:''}`;
 if(c.type==='number')return `<p class="question small">Anong bilang ito?</p><div class="question-number" style="margin:10px 0">${c.number}</div><div class="number-dots" aria-label="${c.number} counting dots">${'<i></i>'.repeat(c.number)}</div>${r?`<div class="answer">${esc(c.answer)}</div>`:''}`;
 if(c.type==='animal')return `<p class="question small">Anong hayop ito?</p><img class="animal-pic" src="assets/${esc(c.asset)}.webp" alt="Animal to identify">${r?`<div class="answer">${esc(c.answer)}</div>`:''}`;
 if(c.type==='german')return `<p class="question small">How do you say this in German?</p><div class="word phrase">${esc(c.english)}</div>${r?`<div class="answer">${esc(c.answer)}</div>`:'<p class="caption">Say your answer, then tap Help me to listen.</p>'}`;
 if(c.type==='prayer'||c.type==='prayerFull')return `<span class="track-badge">${c.type==='prayerFull'?(c.build?'First '+c.build+' lines':'The whole recitation'):'Line '+c.line+' of 13'}</span>${r?`<div class="${c.type==='prayerFull'?'prayer-full':'prayer-line'}">${esc(c.answer)}</div>`:`<div class="question">${c.type==='prayerFull'?'Can you say it from memory?':'Try saying this line from memory.'}</div><div class="word">🕊️</div>`}<p class="caption">One line, one little step. Take your time.</p>`;
 if(c.type==='countries')return `<p class="question">${esc(c.prompt)}</p><div style="font-size:70px;margin:20px">🌏</div>${r?`<div class="country-tags">${c.countries.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:'<p class="caption">Try naming the places you remember.</p>'}`;
 return `<p class="question ${c.diagram?'small':''}">${esc(c.prompt)}</p>${c.diagram?anatomy(c):`<div style="font-size:65px;margin:20px">${c.icon||'💭'}</div>`}${r?`<div class="answer ${c.answer.length>55?'long':''}">${esc(c.answer)}</div>`:''}`;
}
function finish(){return `<section class="success">${owl()}<div class="eyebrow">LOOK AT YOU GROW!</div><h1>Lovely practice!</h1><p>You finished ${session.done} little activities.<br>Every try is a step forward.</p><span class="pill gold">★ +${session.done} practice stars</span><p style="font-size:12px">${session.correct?`${session.correct} correct selections. `:''}Spoken answers are practice, ready for a grown-up to check.</p><div class="button-row" style="justify-content:center"><button class="primary" data-action="page" data-page="home">All done for now ${icon('home')}</button><button class="secondary" data-action="page" data-page="lessons">Choose a lesson</button></div></section>`;}
function starPage(){const pr=Object.values(progress);return `<div class="eyebrow">EVERY LITTLE TRY COUNTS</div><h1 class="page-title mt">Look how you’re growing!</h1><p class="page-sub">These stars celebrate your practice. Keep taking little steps.</p><div class="stats-grid"><div class="stat"><b>★ ${stars}</b><small>Practice stars</small></div><div class="stat"><b>${sessions}</b><small>Finished sessions</small></div><div class="stat"><b>${pr.filter(p=>p.views).length}</b><small>Activities explored</small></div></div><section class="success">${owl()}<h2>${stars?'You’re a little explorer!':'Your adventure starts here.'}</h2><p>${stars?'A little reading. A little thinking. A lot of trying.':'Try your first activity and collect a practice star.'}</p><button class="primary" data-action="start">${icon('play')} Let’s practice</button></section>`;}
function parent(){const all=makeCards(data,'catholic').concat(makeCards(data,'nonCatholic'));const unique=new Map(all.map(c=>[c.id,c]));const practiced=[...unique.values()].filter(c=>progress[c.id]);const recorded=Object.keys(manifest.clips||{}).length;return `<div class="eyebrow">A LITTLE SPACE FOR GROWN-UPS</div><h1 class="page-title mt">Set up a good little session</h1><p class="page-sub">A few thoughtful settings, then your little explorer can take the lead.</p><section class="parent-section"><h2>Religion review</h2><p>Choose the option provided by your school. Only the selected lessons appear during practice.</p><div class="religion-options">${[['catholic','Roman Catholic','Latin Our Father','46'],['nonCatholic','Non-Roman Catholic','Psalm 23:1–4','39']].map(([v,n,rec,num])=>`<button class="religion-option ${settings.track===v?'active':''}" aria-pressed="${settings.track===v}" data-action="track" data-value="${v}"><b>${settings.track===v?'✓ ':''}${n}</b><small>${rec}<br>Old Testament: ${num} books<br>New Testament: 27 books</small></button>`).join('')}</div><p>Switching keeps other subjects’ progress. Each recitation and its track-specific answer have their own progress.</p></section><section class="parent-section"><h2>Practice rhythm</h2><div class="setting-row"><label for="length">Activities per session<small>Choose a limit, or let a parent decide when to stop</small></label><select id="length" data-setting="length">${[0,5,8,12].map(v=>`<option ${settings.length===v?'selected':''} value="${v}">${v===0?'No activity limit (parent decides)':v+' activities'}</option>`).join('')}</select></div><div class="setting-row"><label for="pause">Time for an answer<small>Applies when automatic pacing is on</small></label><select id="pause" data-setting="pause">${[5,8,12,20].map(v=>`<option ${settings.pause===v?'selected':''} value="${v}">${v} seconds</option>`).join('')}</select></div><div class="setting-row"><label for="mode">Starting mode</label><select id="mode" data-setting="mode"><option value="learn" ${settings.mode==='learn'?'selected':''}>Listen & learn</option><option value="recall" ${settings.mode==='recall'?'selected':''}>Try myself</option></select></div><div class="setting-row"><label for="slow">Slower speech</label><input id="slow" type="checkbox" data-setting="slow" ${settings.slow?'checked':''}></div><div class="setting-row"><label for="auto">Automatic pacing<small>Questions, answer pauses, then model answers</small></label><input id="auto" type="checkbox" data-setting="auto" ${settings.auto?'checked':''}></div><details class="inline-details"><summary>Lessons in reviewer practice</summary><div class="subject-checks">${subjects.map(s=>`<label><input type="checkbox" data-subject="${s.id}" ${settings.enabled.includes(s.id)?'checked':''}> ${s.icon} ${s.title}</label>`).join('')}</div></details></section><section class="parent-section"><h2>Voice & audio</h2><p>${recorded?`${esc(manifest.selectedVoice || 'Jessica')} narrates the English, Filipino, and German lessons. Replaying these saved recordings uses no generation credits.`:'Jessica is selected. Recordings are being prepared; matching device voices are used when available.'} The Latin Our Father still needs a verified Latin recording; a matching device voice is used only if available.</p><div class="button-row"><button class="secondary" data-action="test-voice" data-lang="en-US">Test English</button><button class="secondary" data-action="test-voice" data-lang="fil-PH">Test Filipino</button><button class="secondary" data-action="test-voice" data-lang="de-DE">Test German</button><button class="secondary" data-action="test-voice" data-lang="la">Test Latin</button></div><p id="voice-result" role="status"></p><details class="inline-details"><summary>Subject audio practice & scripts</summary><p>Question-and-answer playlists run inside the app with the saved lesson recordings. Picture questions need their on-screen image. The Latin prayer is the only language still awaiting a studio recording.</p><div class="audio-pack"><select id="audio-subject">${[4,5,6,7,9,10,13].map(n=>`<option value="${n}">${subjects.find(s=>s.id===n).title}</option>`).join('')}</select><select id="audio-mode"><option value="answers">Questions, pause, answers</option><option value="questions">Questions only</option></select><button class="secondary" data-action="audio-practice">Play review</button><button class="secondary" data-action="export-scripts">Download scripts</button></div></details></section><section class="parent-section"><h2>Progress you can trust</h2><p>Stars mean practice. Selections can be checked automatically; spoken reading and recitation are not automatically graded. Mark an activity “Parent checked” after hearing it yourself.</p><div class="stats-grid"><div class="stat"><b>${practiced.length}</b><small>Seen activities</small></div><div class="stat"><b>${practiced.filter(c=>progress[c.id].needsHelp).length}</b><small>Need another try</small></div><div class="stat"><b>${practiced.filter(c=>progress[c.id].parentChecked).length}</b><small>Parent checked</small></div></div><details class="inline-details"><summary>Review practiced activities (${practiced.length})</summary>${practiced.length?practiced.map(c=>`<div class="progress-row"><div>${esc(label(c))}<br><span class="status">${statusOf(progress[c.id])}</span></div><button data-action="parent-check" data-key="${esc(c.id)}">${progress[c.id].parentChecked?'Undo check':'Parent checked'}</button></div>`).join(''):'<p>No activities practiced yet.</p>'}</details><div class="button-row"><button class="secondary" data-action="export-progress">Export progress</button><button class="danger" data-action="reset">Reset progress</button></div><p>Saved on this device and browser. Clearing browser data removes local progress.</p></section><section class="parent-section"><h2>Notes from the school reviewer</h2><p>The numbered handout sets the scope. Items 1–13 are included; item 14 is outside this version.</p><details class="inline-details"><summary>Content notes and corrections</summary>${data.sourceNotes.map(n=>`<div class="parent-note">${esc(n)}</div>`).join('')}<div class="parent-note">Mathematics prompts cover 131–209, producing answers through 210. The four printed examples are first. The reviewer’s 126 example is outside the stated range.</div><div class="parent-note">Illustrations are taken from your supplied school slides for this private review app. The source grouping of China, Taiwan, and Hong Kong is retained in these adult notes; the spoken list uses the seven main names.</div></details></section><button class="primary" data-action="page" data-page="home">Ready for practice ${icon('next')}</button>`;}
let audio;
function updateAudioState(){const p=$('#player-line'),st=$('#stage-text'),pc=$('#practice-card');pc?.classList.toggle('speaking',audioState==='playing');if(p)p.textContent=audioState==='playing'?'Listen… then it’s your turn.':audioState==='unavailable'?'This language needs a recording. Please ask a grown-up.':audioState==='error'?'Sound paused. Tap Again to try once more.':'Your turn. Take your time.';if(st&&audioState==='playing')st.textContent='Listen with Ollie';else if(st)st.textContent=session?.revealed?'Now you say it':'Your turn to try';}
function dialog(title,body){$('#modal').innerHTML=`<h2>${title}</h2>${body}`;$('#modal').showModal();}
function parentGate(){stop();const a=3+Math.floor(Math.random()*6),b=5+Math.floor(Math.random()*5);dialog('Hello, grown-up!',`<p>To open parent settings, what is ${a} + ${b}?</p><form id="gate-form"><label for="gate-answer" class="caption">Your answer</label><input id="gate-answer" type="number" inputmode="numeric" autocomplete="off" required><div class="button-row"><button class="primary" type="submit">Open settings</button><button class="secondary" type="button" data-action="close-modal">Back</button></div><p id="gate-error" role="status"></p></form>`);$('#gate-form').onsubmit=e=>{e.preventDefault();if(Number($('#gate-answer').value)===a+b){$('#modal').close();go('parent');}else $('#gate-error').textContent='Please try that once more.';};}
function download(name,value){const blob=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function handleAction(el){const a=el.dataset.action;
 if(a==='page')return go(el.dataset.page);
 if(a==='topic'){topic=Number(el.dataset.id);return go('topic');}
 if(a==='filter'){filter=el.dataset.value;return render();}
 if(a==='parent')return parentGate();
 if(a==='close-modal'){if($('#modal').open)$('#modal').close();return;}
 if(a==='start')return begin(Number(el.dataset.id)||0,el.dataset.all==='true');
 if(a==='card')return begin(0,false,cards.find(c=>c.id===el.dataset.key));
 if(a==='full-prayer'){const c=cards.find(c=>c.id===`prayer-${settings.track}-full`);if(c){begin(8,false,c);if(!session.revealed)reveal(false);}return;}
 if(a==='build-prayer'){stop();session={q:cards.filter(c=>c.item===8&&c.build),index:0,subject:8,mode:'learn',revealed:false,helped:false,selected:null,feedback:'',done:0,correct:0,repeated:new Set()};page='practice';prepareCard();return;}
 if(a==='anatomy'){stop();session={q:cards.filter(c=>c.type==='anatomy'&&c.diagram===el.dataset.id),index:0,subject:5,mode:'learn',revealed:false,helped:false,selected:null,feedback:'',done:0,correct:0,repeated:new Set()};page='practice';prepareCard();return;}
 if(a==='mode'){stop();session.mode=el.dataset.value;return prepareCard();}
 if(a==='next')return next();
 if(a==='replay'){stop();const c=card(),part=session.revealed?'answer':'prompt';return audio.play(c[part],c[part+'Lang'],c.id+':'+part,settings.slow);}
 if(a==='reveal')return reveal(!session.revealed);
 if(a==='pause'){stop();const p=$('#player-line');if(p)p.textContent='Paused. Take your time. Tap Again or Next when ready.';return;}
 if(a==='choice'){stop();const c=card(),v=session.choices[Number(el.dataset.index)];session.selected=v;if(v===c.correct){progress=recordProgress(progress,c.id,'correct');session.correct++;session.feedback='✓ That’s the right choice! Now say it out loud.';save();return reveal(false);}session.helped=true;progress=recordProgress(progress,c.id,'help');session.feedback='A little hint will help. Listen, then try again later.';save();return reveal(false);}
 if(a==='part'){stop();partFocus=el.dataset.value;render();return audio.play(partFocus,'en-US',card().id+':part:'+partFocus,settings.slow);}
 if(a==='leave'){stop();dialog('Take a little break?',`<p>Your finished activities are saved.</p><div class="button-row"><button class="primary" data-action="confirm-leave">Back home</button><button class="secondary" data-action="close-modal">Keep practicing</button></div>`);return;}
 if(a==='confirm-leave'){$('#modal').close();return go('home');}
 if(a==='track'){stop();settings.track=el.dataset.value;cards=makeCards(data,settings.track);save();render();return toast(`${trackName()} lessons selected.`);}
 if(a==='test-voice'){const lang=el.dataset.lang,text={'en-US':'Hello, little explorer. Let’s practice together!','fil-PH':'Anong hayop ito? Aso. Magaling!','de-DE':'Name. Datum. Übung.','la':'Pater noster, qui es in caelis.'}[lang];const ok=await audio.play(text,lang,'test:'+lang,settings.slow);const result=$('#voice-result');if(result)result.textContent=ok?'Audio test finished.':'No playable recording or suitable device voice for this language yet.';return;}
 if(a==='audio-practice'){const n=Number($('#audio-subject').value),only=$('#audio-mode').value==='questions';settings.auto=true;save();return begin(n,true,null,only);}
 if(a==='parent-check'){progress=recordProgress(progress,el.dataset.key,'parent');save();return render();}
 if(a==='export-scripts'){const entries=audioEntries([...new Map([...makeCards(data,'catholic'),...makeCards(data,'nonCatholic')].map(c=>[c.id,c])).values()]);return download('kinder-review-audio-scripts.json',{title:'Kinder Review Buddy',note:'Separate question and answer clips. Both religion tracks included.',entries});}
 if(a==='export-progress')return download('kinder-review-progress.json',{exportedAt:new Date().toISOString(),settings,progress,stars,sessions});
 if(a==='reset'){dialog('Reset practice progress?',`<p>This removes stars and practice history on this device. Your lesson settings stay the same.</p><div class="button-row"><button class="danger" data-action="confirm-reset">Reset progress</button><button class="secondary" data-action="close-modal">Keep progress</button></div>`);return;}
 if(a==='confirm-reset'){progress={};stars=0;sessions=0;settings.reviewerAfter={};save();$('#modal').close();render();return toast('Progress reset. A fresh little start.');}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled)handleAction(el).catch(err=>{console.error(err);toast('Something paused. Please try again.');});});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.setting){const k=el.dataset.setting;settings[k]=el.type==='checkbox'?el.checked:['length','pause'].includes(k)?Number(el.value):el.value;save();if(page==='practice'&&k==='auto'){stop();if(settings.auto)playInitial();}}if(el.dataset.subject){const id=Number(el.dataset.subject);settings.enabled=el.checked?[...new Set([...settings.enabled,id])]:settings.enabled.filter(n=>n!==id);save();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
try{[data,manifest]=await Promise.all([fetch('./lessons.json').then(r=>{if(!r.ok)throw Error('Lessons failed');return r.json();}),fetch('./audio-manifest.json?v=3',{cache:'no-store'}).then(r=>r.json())]);cards=makeCards(data,settings.track);audio=new BuddyAudio(manifest,(state,lang)=>{audioState=state;updateAudioState();if(state==='unavailable'&&page==='practice'){const note=$('#audio-note');if(note)note.textContent=`A ${lang==='la'?'Latin':lang.startsWith('fil')?'Filipino':lang.startsWith('de')?'German':'English'} recording or matching device voice is needed. A grown-up can check Voice & audio in settings.`;}});render();}catch(error){$('#app').innerHTML='<div class="loading"><h2>Your lessons could not load.</h2><p>Please reconnect and refresh the page.</p><button onclick="location.reload()">Try again</button></div>';console.error(error);}
